using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasIndex(p => p.Sku);

            // BREAKING CHANGE 1: EF Core 9 renamed the discriminator JSON property
            // from "Discriminator" to "$type". Existing 500K documents use "Discriminator",
            // and direct SQL queries (c.Discriminator) depend on this name.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2: EF Core 9 changed the id format from
            // "EntityType|Key" (e.g. "Product|123") to just the key value ("123").
            // Existing documents use the old format. We preserve it via a shadow property.
            entity.Property<string>("__id")
                  .ToJsonPropertyName("id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();
            entity.HasKey("__id");
        });
    }
}

