using Microsoft.EntityFrameworkCore;

class CosmosQuery
{
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still references "Discriminator" (not "$type") because we
        // configured HasDiscriminator("Discriminator") in OnModelCreating.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // BREAKING CHANGE 3: Synchronous I/O is no longer supported in EF Core 9 Cosmos.
        // All queries must use async APIs (ToListAsync, FirstOrDefaultAsync, etc.)
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

